import{_ as t}from"./chunks/vscode-heal.B4mhIb6w.js";import{_ as a,o as r,c as i,a6 as o}from"./chunks/framework.CCKCzdWs.js";const g=JSON.parse('{"title":"Editor extensions","description":"Piwi in VS Code and the JetBrains IDEs: tests recorded at the cursor, the latest CI failures at their failing lines with your local runs laid over them and the heal as a quick fix, the tests behind each locator, file and line, brittle locators, and the locators an unsaved change breaks.","frontmatter":{"title":"Editor extensions","description":"Piwi in VS Code and the JetBrains IDEs: tests recorded at the cursor, the latest CI failures at their failing lines with your local runs laid over them and the heal as a quick fix, the tests behind each locator, file and line, brittle locators, and the locators an unsaved change breaks.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/editors.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/editors.html"}],["meta",{"property":"og:title","content":"Editor extensions | Piwi Dashboard"}],["meta",{"property":"og:description","content":"Piwi in VS Code and the JetBrains IDEs: tests recorded at the cursor, the latest CI failures at their failing lines with your local runs laid over them and the heal as a quick fix, the tests behind each locator, file and line, brittle locators, and the locators an unsaved change breaks."}]]},"headers":[],"relativePath":"features/editors.md","filePath":"features/editors.md","lastUpdated":1793046053000}'),s={name:"features/editors.md"};function n(h,e,d,l,c,u){return r(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="editor-extensions" tabindex="-1">Editor extensions <a class="header-anchor" href="#editor-extensions" aria-label="Permalink to &quot;Editor extensions&quot;">​</a></h1><p>The Piwi extension for VS Code (and Cursor, VSCodium) and the Piwi plugin for the JetBrains IDEs with the LSP API (WebStorm, IntelliJ IDEA Ultimate, Rider, from 2024.1) bring what the dashboard knows about your suite to the line you are editing. Both run the same editor service; the <a href="./jetbrains.html">JetBrains plugin</a> page lists what the plugin needs and draws differently.</p><figure><img src="'+t+'" alt="VS Code: a CI failure at its line, the heal offered as a quick fix"><figcaption>The latest run&#39;s failure at its line, and the heal as a quick fix.</figcaption></figure><h2 id="install-and-connect" tabindex="-1">Install and connect <a class="header-anchor" href="#install-and-connect" aria-label="Permalink to &quot;Install and connect&quot;">​</a></h2><p>Install <strong>Piwi</strong> from the <strong><a href="https://marketplace.visualstudio.com/items?itemName=PiwiTests.piwi" target="_blank" rel="noreferrer">Visual Studio Marketplace ↗</a></strong> (<code>piwitests.piwi</code> in the extensions view) or the <strong><a href="https://plugins.jetbrains.com/plugin/34674-piwi" target="_blank" rel="noreferrer">JetBrains Marketplace ↗</a></strong> (<strong>Settings → Plugins</strong>). It starts on a trusted workspace that holds a Playwright config, and reads the connection the reporter already uses: the <code>PIWI_*</code> variables in the environment or the workspace <code>.env</code>, or the <a href="/features/desktop.html">desktop app</a>. Otherwise, run <strong>Piwi: Connect</strong> (<strong>Settings → Tools → Piwi</strong> in a JetBrains IDE) and sign in with the browser: <a href="./editor-connection.html">Editor connection</a> has the steps. In VS Code, the extension also opens a path clicked in the dashboard, with no workspace root to set: <a href="./ide-integration.html#vs-code-the-piwi-extension">Open in IDE</a>.</p><p>In VS Code, the first workspace with a Playwright config opens the <strong>Get started with Piwi</strong> walkthrough, once per machine, unless <code>workbench.welcomePage.walkthroughs.openOnInstall</code> is off; <strong>Piwi: Get started</strong> opens it again. Its steps connect, open the latest CI run&#39;s failures, run the failing tests, record a test, give your agent the MCP server and open the settings. A JetBrains IDE shows one notification instead: <a href="./jetbrains.html#install-and-start">JetBrains plugin</a>.</p><p>Nothing from your workspace is sent to the instance: the project&#39;s <a href="/guide/concepts.html#locator-index">locator index</a>, <a href="/features/code-reach.html">code reach</a> and latest run are compared with your files locally.</p><h2 id="ci-failures-in-the-problems-panel" tabindex="-1">CI failures in the Problems panel <a class="header-anchor" href="#ci-failures-in-the-problems-panel" aria-label="Permalink to &quot;CI failures in the Problems panel&quot;">​</a></h2><p>The failures of the latest complete <a href="/reference/test-metadata.html#run-origin">CI run</a> on the checked-out branch, else the default branch, are in the Problems panel at the line that failed, with your local runs laid over them, and each failing line follows your edits until a run covers its test again. The heal, the trace, a rerun and the fix plan are quick fixes on the failure, and the failures view lists them as a tree: <a href="./editor-failures.html">Failures in the editor</a>.</p><h2 id="the-tests-behind-each-line" tabindex="-1">The tests behind each line <a class="header-anchor" href="#the-tests-behind-each-line" aria-label="Permalink to &quot;The tests behind each line&quot;">​</a></h2><p>Lines above the code (CodeLens):</p><table tabindex="0"><thead><tr><th>File</th><th>What it shows</th><th>Click</th></tr></thead><tbody><tr><td>A spec</td><td>the tests Piwi knows in it; beside each <code>test(…)</code>, its latest result in the gutter, a failing test&#39;s body tinted, and on hover its pass rate, <a href="/features/flaky-tests.html">flaky</a> score and root cause, quarantine and selections</td><td>opens the test in the dashboard</td></tr><tr><td>A page object or spec</td><td>above each locator line, the tests using it, their actions, and how many fail or are flaky</td><td>runs those tests</td></tr><tr><td>An application file</td><td>the tests that reach it, from <a href="/features/code-reach.html">code reach</a>; with <a href="./editor-coverage.html">coverage</a>, each function&#39;s too</td><td>runs those tests</td></tr><tr><td>A page file (Nuxt <code>pages/**</code>)</td><td>the tests acting on that page, its locators and how many are brittle</td><td>runs those tests</td></tr></tbody></table><p>Above a flaky test: its flaky rate and <a href="./flake-lab.html#from-the-editor-and-the-failure-pages">top suspect</a>, then <strong>Reproduce this flake</strong> and, once reproduced, <strong>Verify the flake fix</strong>, which run <code>piwi flake</code>; beside a team instance, <strong>Reproduce this flake in the desktop app</strong>.</p><h2 id="timeouts" tabindex="-1">Timeouts <a class="header-anchor" href="#timeouts" aria-label="Permalink to &quot;Timeouts&quot;">​</a></h2><p>A test whose <code>test.slow()</code> is no longer needed, or whose timeout is far above its p95, gets a note on its line and a quick fix: remove the <code>test.slow()</code>, or set <code>test.setTimeout</code> to the suggested value.</p><h2 id="completion" tabindex="-1">Completion <a class="header-anchor" href="#completion" aria-label="Permalink to &quot;Completion&quot;">​</a></h2><ul><li>After a page and a <code>.</code> in a spec or a page object: the locator chains your suite already uses on the pages this file&#39;s tests visit, most used first and brittle ones last. The page is <code>page</code>, <code>this.page</code>, or any page the code at the cursor can use, the same ones <a href="/features/editor-recording.html#start-a-recording">a recording</a> offers: another page fixture of the test (<code>adminPage.</code>), a page object&#39;s page field (<code>this.root.</code>), a page the test opens (<code>newPage()</code>, a popup).</li><li>Right after <code>expect(</code>: the same chains on the page in use there, such as <code>page.getByRole(&#39;button&#39;, { name: &#39;Pay&#39; })</code>, so an assertion&#39;s locator is written in one step.</li><li>At the start of a statement: the <a href="/features/test-functions.html">functions</a> of your catalog whose URL pattern matches those pages, as a call with a placeholder per parameter.</li><li>In a <code>piwi:</code> annotation: the types (<code>piwi:owner</code>, <code>piwi:priority</code>, <code>piwi:feature</code>, <code>piwi:link</code>), then the owners, priorities or features they take; in <code>tag: [&#39;@…&#39;]</code>, the tags your tests already use.</li></ul><h2 id="brittle-locators" tabindex="-1">Brittle locators <a class="header-anchor" href="#brittle-locators" aria-label="Permalink to &quot;Brittle locators&quot;">​</a></h2><p>A locator the <a href="/reference/locator-stability.html">stability rules</a> rate brittle is a warning on its line; one worth a look is a hint. When the capture fixtures stored a stable alternative for that call site on its last passing run, the quick fix replaces the chain with it.</p><h2 id="the-locators-a-change-breaks" tabindex="-1">The locators a change breaks <a class="header-anchor" href="#the-locators-a-change-breaks" aria-label="Permalink to &quot;The locators a change breaks&quot;">​</a></h2><p>In an application file, the unsaved buffer is compared with <code>HEAD</code> as you type, the same way <a href="/features/preflight.html"><code>piwi preflight</code></a> compares a diff. A changed line whose string a locator finds its element by is a warning, with the chains it breaks on hover, and one quick fix that rewrites every call site.</p><h2 id="piwi-s-mcp-server-for-the-agent" tabindex="-1">Piwi&#39;s MCP server for the agent <a class="header-anchor" href="#piwi-s-mcp-server-for-the-agent" aria-label="Permalink to &quot;Piwi&#39;s MCP server for the agent&quot;">​</a></h2><p>In VS Code 1.101 and later, the extension provides Piwi&#39;s <a href="/features/mcp.html">MCP server</a> to the editor&#39;s agent with the connection it already has. Elsewhere, <strong>Piwi: Copy the MCP server configuration</strong> puts an entry on the clipboard: for <code>mcp.json</code> in VS Code, for the AI Assistant&#39;s MCP settings in a JetBrains IDE (an <code>mcpServers</code> entry running <code>mcp-remote</code>). It holds your API key, so paste it into your user settings, not into the repository.</p><p>The key carries your whole role, write tools included. For a token of the agent&#39;s own, set <code>piwi.mcpAuthorization</code> to <code>sign-in</code> (<strong>Settings → Tools → Piwi → AI Assistant</strong> in a JetBrains IDE): the server comes without a key, and the agent <a href="/features/mcp.html#authentication">signs in</a> in your browser when it first connects. You revoke that token with your API keys. The desktop app keeps its own token.</p><h2 id="commands" tabindex="-1">Commands <a class="header-anchor" href="#commands" aria-label="Permalink to &quot;Commands&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>What it does</th></tr></thead><tbody><tr><td>Piwi: Connect, Disconnect</td><td>See <a href="./editor-connection.html">Editor connection</a></td></tr><tr><td>Piwi: Refresh</td><td>Fetch the indexes and the latest run again</td></tr><tr><td>Piwi: Refresh the latest run</td><td>Read the latest run again, as a click on the status bar does</td></tr><tr><td>Piwi: Run the test at the cursor</td><td>Run the test whose <code>test(…)</code> call holds the cursor: <a href="./editor-runs.html#run-tests">Run tests</a></td></tr><tr><td>Piwi: Verify the test at the cursor ×3</td><td>Run it three times without retries and say how many runs passed</td></tr><tr><td>Piwi: Run this spec</td><td>Run the tests of the spec Piwi knows</td></tr><tr><td>Piwi: Run the tests that reach this file</td><td>Run them in a terminal, as <code>piwi run</code> would</td></tr><tr><td>Piwi: Re-run the failing tests</td><td>Run every test still failing: <a href="./editor-runs.html#re-run-the-failing-tests">Re-run the failing tests</a></td></tr><tr><td>Piwi: Open in dashboard</td><td>Open this file&#39;s test, or the latest run</td></tr><tr><td>Piwi: Run selection…</td><td>Run a saved <a href="/features/test-selection.html">selection</a></td></tr><tr><td>Piwi: Open the latest run</td><td>Open the run the status bar shows</td></tr><tr><td>Piwi: Compare with…</td><td>Choose the run the failures are read against: <a href="./editor-failures.html#compare-with-another-run">Compare with another run</a></td></tr><tr><td>Piwi: Pair with Piwi Picker</td><td>Copy the address <a href="./editor-recording.html#send-from-piwi-picker">Piwi Picker sends to</a></td></tr><tr><td>Piwi: Record here, Record a new test file</td><td>Record at the cursor, or into a new spec: <a href="./editor-recording.html">Record tests from the editor</a></td></tr><tr><td>Piwi: Stop recording, Pause recording, Resume recording</td><td>Control the recording in progress</td></tr><tr><td>Piwi: Toggle the coverage marks</td><td>Show or hide the <a href="./editor-coverage.html">coverage marks</a></td></tr><tr><td>Piwi: Open the log</td><td>Show the editor service&#39;s log; the <code>piwi.trace.server</code> setting adds its traffic</td></tr><tr><td>Piwi: Get started</td><td>Open the walkthrough</td></tr></tbody></table><p>Three commands have a shortcut, the same in VS Code and the JetBrains IDEs and free in their default keymaps on Windows, Linux and macOS: <code>Ctrl+Shift+Alt+K</code> runs the test at the cursor, <code>Ctrl+Shift+Alt+F</code> re-runs the failing tests, and <code>Ctrl+Shift+Alt+R</code> records at the cursor, then stops the recording; on macOS, <code>Cmd</code> takes the place of <code>Ctrl</code>. <strong>Preferences: Open Keyboard Shortcuts</strong> changes them in VS Code (search <code>piwi</code>), <strong>Settings → Keymap</strong> in a JetBrains IDE (search <code>Piwi</code>).</p><h2 id="jetbrains-ides" tabindex="-1">JetBrains IDEs <a class="header-anchor" href="#jetbrains-ides" aria-label="Permalink to &quot;JetBrains IDEs&quot;">​</a></h2><p>The plugin runs in WebStorm, IntelliJ IDEA Ultimate, Rider and the other JetBrains IDEs with the LSP API, with the project&#39;s Node.js interpreter, 20 or later. It shows the failures in the Piwi tool window, the lines above the code with Code Vision, and its actions under <strong>Tools → Piwi</strong>: <a href="./jetbrains.html">JetBrains plugin</a>.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./editor-failures.html">Failures in the editor</a>: the CI failures at their lines, the quick fixes and the failures view.</li><li><a href="./editor-runs.html">Runs from the editor</a>: run tests, and follow the run in the status bar.</li><li><a href="./editor-recording.html">Record tests from the editor</a>: steps written at the cursor as you take them in a browser.</li><li><a href="./editor-connection.html">Editor connection</a>: the instance the editor reads, and its key.</li></ul>',31)])])}const m=a(s,[["render",n]]);export{g as __pageData,m as default};
